  { channelId: 'UCagiBBx1prefrlsDzDxuA9A', channelName: 'Solving The Money Problem' },
  { channelId: 'UCj--iMtToRO_cGG_fpmP5XQ', channelName: 'Munro Live' },
  // LATAM
  { channelId: 'UCVSmP_xSMQCi-DCpsLphUhA', channelName: 'Automotive Business' },
  { channelId: 'UCKGEe_onHtps2aGf7FvMEwg', channelName: 'AutoData' },
  { channelId: 'UCLI4tg1oh_oLiJJteExJdUQ', channelName: 'AutoForce' },
