  { channelId: 'UCnmWhWiag0PGQ1-C5F7Yq-Q', channelName: 'JATO Dynamics' },
  // Europa
  { channelId: 'UCntjlgM9ueAagCetcC1fAkA', channelName: 'Automotive News' },
  { channelId: 'UCu_i0NkUjKzHVF1pzGfDARw', channelName: 'Fully Charged Show' },
