  // Varejo/operação de concessionárias (EUA)
  { channelId: 'UCxVAdOU294AbW5P1IO5vGUQ', channelName: 'Car Dealership Guy' },
  { channelId: 'UCb5pbAY6geG48o5mN796cvw', channelName: 'JM&A Group' },
  { channelId: 'UCPKZSUgHnKOk0xz1Ywf6mlw', channelName: 'Dealer Tech Talk Podcast' },
  { channelId: 'UC3xj69kUFavbRAb2MSd3Bmg', channelName: 'Selly Automotive' },
  // China/global — mesma empresa da Autohome (汽车之家), rebrand internacional
  { channelId: 'UCJkj4A_k8RYCebeguJU_zkQ', channelName: 'yesauto.' },
];

// Janela de busca: 7 dias (semanal). Para bi-semanal, use 14 e ajuste o trigger.
const DIAS_JANELA = 7;

// Teto de vídeos mais recentes por canal, por rodada. yt-dlp não tem cota
// paga (ao contrário da RapidAPI usada na v1 deste pipeline), mas o teto
// continua valendo como limite de custo de GPU/tempo do Ollama — sem ele,
// canais que postam quase diariamente sozinhos já geram dezenas de vídeos
// por rodada.
const MAX_VIDEOS_POR_CANAL = 3;

// Fail-fast: sem credenciais não há o que executar.
for (const nome of ['YOUTUBE_API_KEY', 'TELEGRAM_BOT_TOKEN', 'TELEGRAM_CHAT_ID']) {
  if (!$env[nome]) {
    throw new Error('Variável de ambiente ausente no container n8n: ' + nome + ' (ver agents/youtube-etl/README.md)');
  }
}

const publishedAfter = new Date(Date.now() - DIAS_JANELA * 24 * 60 * 60 * 1000).toISOString();
return CANAIS.map((c) => ({
  json: {
    ...c,
    uploadsPlaylistId: 'UU' + c.channelId.slice(2), // uploads playlist = UC->UU
    publishedAfter,
    maxVideos: MAX_VIDEOS_POR_CANAL,
  },
}));

// Achata as respostas da search.list em 1 item por vídeo.
// Canal com erro na API não derruba o run: vira entrada em `falhas`.
const videos = [];
const falhas = [];
const entradas = $input.all();

for (let i = 0; i < entradas.length; i++) {
  const r = entradas[i].json;
  const canal = $('Config Canais').itemMatching(i).json.channelName;
  if (r.error) {
    const detalhe = (r.error.message || JSON.stringify(r.error)).slice(0, 200);
    falhas.push(canal + ': erro na YouTube API — ' + detalhe);
    continue;
  }
  const publishedAfter = $('Config Canais').itemMatching(i).json.publishedAfter;
  for (const v of r.items || []) {
    const videoId = v.snippet && v.snippet.resourceId && v.snippet.resourceId.videoId;
    if (!videoId) continue;
    const publicadoEm = (v.snippet && v.snippet.publishedAt) || '';
    if (publicadoEm && publishedAfter && publicadoEm < publishedAfter) continue; // fora da janela
    videos.push({
      videoId,
      titulo: (v.snippet && v.snippet.title) || '(sem título)',
      canal: (v.snippet && v.snippet.channelTitle) || canal,
      publicadoEm,
    });
  }
}

if (videos.length === 0) {
  // Sentinela: mantém o fluxo vivo até o relatório/notificação de semana vazia.
  return [{ json: { semVideos: true, falhas } }];
}

videos[0].falhas = falhas;
return videos.map((v) => ({ json: v }));

const SYSTEM_PROMPT = [
  'Você é um Engenheiro de Dados e Estrategista de Mercado Automotivo.',
  'Sua tarefa é analisar a transcrição de um vídeo e extrair métricas e tendências críticas, descartando todo o ruído, opiniões não fundamentadas e introduções.',
  '',
  'Regras de Extração:',
  '1. Extraia apenas dados factuais relacionados a: Demanda global/regional, Incentivos/Subsídios, Números de vendas, e Métricas de Performance (CVR, CTR, CPA, margens).',
  '2. Se um dado ou métrica específica não for mencionado no texto fornecido, você DEVE retornar null. Não infira, não invente.',
  '3. Mantenha os resumos extremamente concisos (máximo de 2 frases por campo).',
  '',
  'Regra de Formatação (CRÍTICA):',
  'O seu output DEVE ser ÚNICA e EXCLUSIVAMENTE um objeto JSON válido. Não inclua nenhuma formatação markdown (como ```json), explicações, saudações ou texto antes ou depois do JSON.',
  '',
  'Estrutura obrigatória do JSON:',
  '{',
  '  "assunto_principal": "string",',
  '  "demanda_estoque": "string ou null",',
  '  "incentivos_subsidios": "string ou null",',
  '  "metricas_performance": {',
  '    "cvr_taxa_conversao": "string ou null",',
  '    "ctr_cliques": "string ou null",',
  '    "vendas_volume": "string ou null"',
  '  },',
  '  "insight_estrategico": "string (Apenas se houver uma oportunidade clara de produto ou negócio baseada nos dados)"',
  '}',
].join('\n');

const OUTPUT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: [
    'assunto_principal',
    'demanda_estoque',
    'incentivos_subsidios',
    'metricas_performance',
    'insight_estrategico',
  ],
  properties: {
    assunto_principal: { type: 'string' },
    demanda_estoque: { type: ['string', 'null'] },
    incentivos_subsidios: { type: ['string', 'null'] },
    metricas_performance: {
      type: 'object',
      additionalProperties: false,
      required: ['cvr_taxa_conversao', 'ctr_cliques', 'vendas_volume'],
      properties: {
        cvr_taxa_conversao: { type: ['string', 'null'] },
        ctr_cliques: { type: ['string', 'null'] },
        vendas_volume: { type: ['string', 'null'] },
      },
    },
    insight_estrategico: { type: ['string', 'null'] },
  },
};

// Limita a entrada para caber junto com schema e saída em num_ctx=8192.
const MAX_CHARS = 24000;

// yt-dlp escreve legenda .vtt em stdout (via `cat` no comando); sem legenda
// disponível, stdout vem vazio. Extrai o texto puro, descartando cabeçalho,
// timestamps e tags inline, com dedupe de linha consecutiva repetida (comum
// em legenda automática).
function extrairTranscricao(j) {
  if (!j || j.error) return '';
  const vtt = typeof j.stdout === 'string' ? j.stdout : '';
  if (!vtt.trim()) return '';
  const linhas = vtt.split(/\r?\n/);
  const out = [];
  let ultima = '';
  for (const linha of linhas) {
    const l = linha.trim();
    if (!l) continue;
    if (l.startsWith('WEBVTT')) continue;
    if (/^\d+$/.test(l)) continue; // número da cue
    if (l.includes('-->')) continue; // linha de timestamp
    if (/^(Kind|Language):/i.test(l)) continue; // metadado do cabeçalho vtt
    const limpo = l.replace(/<[^>]+>/g, '').trim(); // tags inline (<c>, <00:00:01.000>)
    if (!limpo || limpo === ultima) continue; // dedupe de linha repetida
    out.push(limpo);
    ultima = limpo;
  }
  return out.join(' ').replace(/\s+/g, ' ').trim();
}

const entradas = $input.all();
const saida = [];
const semTranscricao = [];
let falhas = [];
let semVideos = false;
let todosAbaixoDoLimiar = false;
let videosIgnorados = [];

for (let i = 0; i < entradas.length; i++) {
  const origem = $('Mesclar Estatisticas').all()[i].json;
  if (origem.falhas) falhas = origem.falhas;
  if (origem.videosIgnorados) videosIgnorados = origem.videosIgnorados;
  if (origem.semVideos) {
    semVideos = true;
    continue;
  }
  if (origem.todosAbaixoDoLimiar) {
    todosAbaixoDoLimiar = true;
    continue;
  }

  const transcricao = extrairTranscricao(entradas[i].json);
  if (!transcricao) {
    semTranscricao.push(origem.canal + ': "' + origem.titulo + '" (https://youtu.be/' + origem.videoId + ')');
    continue;
  }

  saida.push({
    json: {
      videoId: origem.videoId,
      titulo: origem.titulo,
      canal: origem.canal,
      publicadoEm: origem.publicadoEm,
      views: origem.views,
      likes: origem.likes,
      ollamaBody: JSON.stringify({
        model: 'llama3.2',
        stream: false,
        format: OUTPUT_SCHEMA, // JSON estruturado validado durante a geração
        options: { temperature: 0.2, num_ctx: 8192, num_predict: 512 },
        messages: [
          { role: 'system', content: SYSTEM_PROMPT },
          { role: 'user', content: 'TRANSCRIÇÃO DO VÍDEO "' + origem.titulo + '" (canal ' + origem.canal + '):\n\n' + transcricao.slice(0, MAX_CHARS) },
        ],
      }),
    },
  });
}

if (saida.length === 0) {
  // Semana sem nada analisável: chamada mínima ao Ollama só para manter o fluxo
  // linear vivo até o relatório/notificação (custo local desprezível).
  saida.push({
    json: {
      pularAnalise: true,
      ollamaBody: JSON.stringify({
        model: 'llama3.2',
        stream: false,
        format: 'json',
        options: { num_ctx: 2048, num_predict: 5 },
        messages: [{ role: 'user', content: 'Responda apenas {}' }],
      }),
    },
  });
}

saida[0].json.semTranscricao = semTranscricao;
saida[0].json.falhas = falhas;
saida[0].json.semVideos = semVideos;
saida[0].json.todosAbaixoDoLimiar = todosAbaixoDoLimiar;
saida[0].json.videosIgnorados = videosIgnorados;
return saida;

const CAMPOS_TEXTO = ['demanda_estoque', 'incentivos_subsidios'];
const CAMPOS_METRICAS = ['cvr_taxa_conversao', 'ctr_cliques', 'vendas_volume'];

function validarSchema(obj) {
  const erros = [];
  if (typeof obj.assunto_principal !== 'string' || !obj.assunto_principal.trim()) {
    erros.push('assunto_principal ausente ou vazio');
  }
  for (const campo of CAMPOS_TEXTO) {
    if (obj[campo] !== null && obj[campo] !== undefined && typeof obj[campo] !== 'string') {
      erros.push(campo + ' deve ser string ou null');
    }
  }
  const mp = obj.metricas_performance;
  if (!mp || typeof mp !== 'object' || Array.isArray(mp)) {
    erros.push('metricas_performance ausente ou inválido');
  } else {
    for (const campo of CAMPOS_METRICAS) {
      if (mp[campo] !== null && mp[campo] !== undefined && typeof mp[campo] !== 'string') {
        erros.push('metricas_performance.' + campo + ' deve ser string ou null');
      }
    }
  }
  if (obj.insight_estrategico !== null && obj.insight_estrategico !== undefined && typeof obj.insight_estrategico !== 'string') {
    erros.push('insight_estrategico deve ser string');
  }
  return erros;
}

const entradas = $input.all();
const saida = [];

for (let i = 0; i < entradas.length; i++) {
  const origem = $('Montar Prompt Ollama').itemMatching(i).json;
  const meta = {
    videoId: origem.videoId,
    titulo: origem.titulo,
    canal: origem.canal,
    publicadoEm: origem.publicadoEm,
    views: origem.views,
    likes: origem.likes,
    pularAnalise: origem.pularAnalise || false,
    semTranscricao: origem.semTranscricao,
    falhas: origem.falhas,
    semVideos: origem.semVideos,
    todosAbaixoDoLimiar: origem.todosAbaixoDoLimiar,
    videosIgnorados: origem.videosIgnorados,
  };

  if (meta.pularAnalise) {
    saida.push({ json: { ...meta, ok: false } });
    continue;
  }

  const bruto = entradas[i].json.message && entradas[i].json.message.content;
  if (!bruto) {
    const detalhe = JSON.stringify(entradas[i].json).slice(0, 200);
    saida.push({ json: { ...meta, ok: false, erro: 'Ollama não retornou conteúdo (' + detalhe + ')' } });
    continue;
  }

  // Mesmo com format:json, remove cercas markdown defensivamente.
  const limpo = bruto.replace(/```(?:json)?/g, '').trim();
  let analise;
  try {
    analise = JSON.parse(limpo);
  } catch (e) {
    saida.push({ json: { ...meta, ok: false, erro: 'JSON inválido: ' + e.message, bruto: limpo.slice(0, 500) } });
    continue;
  }

  const errosSchema = validarSchema(analise);
  if (errosSchema.length > 0) {
    saida.push({ json: { ...meta, ok: false, erro: 'Schema inválido: ' + errosSchema.join('; '), bruto: limpo.slice(0, 500) } });
    continue;
  }

  saida.push({ json: { ...meta, ok: true, analise } });
}

return saida;

const dataStr = new Date().toISOString().slice(0, 10);
const itens = $input.all().map((i) => i.json);
const meta = itens[0];
const analises = itens.filter((i) => i.ok).sort((a, b) => (b.views ?? -1) - (a.views ?? -1));
const invalidos = itens.filter((i) => !i.ok && !i.pularAnalise);
const videosIgnorados = meta.videosIgnorados || [];

// Formato compacto (1k, 100k, 1MM, 10MM) em vez de separador de milhar cheio.
function fmtNum(n) {
  if (typeof n !== 'number') return '—';
  if (n >= 1000000) return (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'MM';
  if (n >= 1000) return (n / 1000).toFixed(1).replace(/\.0$/, '') + 'k';
  return String(n);
}
const semTranscricao = meta.semTranscricao || [];
const falhas = meta.falhas || [];

const linhas = [];
linhas.push('# YouTube ETL — Mercado Automotivo — ' + dataStr);
linhas.push('');
linhas.push('Análise semanal de transcrições via Ollama (llama3.2). Ordenado por engajamento (views).');
linhas.push('');

if (analises.length === 0) {
  let msg;
  if (meta.semVideos) msg = 'Nenhum vídeo novo encontrado nos canais monitorados no período.';
  else if (meta.todosAbaixoDoLimiar) msg = 'Vídeos novos encontrados, mas nenhum passou do piso de 1.000 views (ver rodapé).';
  else msg = 'Nenhuma análise válida gerada no período (ver rodapé de execução).';
  linhas.push(msg);
  linhas.push('');
}

for (const a of analises) {
  const m = a.analise.metricas_performance || {};
  linhas.push('## ' + a.titulo);
  linhas.push('');
  linhas.push('- **Canal:** ' + a.canal);
  linhas.push('- **Vídeo:** https://youtu.be/' + a.videoId + (a.publicadoEm ? ' (' + a.publicadoEm.slice(0, 10) + ')' : ''));
  linhas.push('- **Views:** ' + fmtNum(a.views) + ' · **Likes:** ' + fmtNum(a.likes));
  linhas.push('- **Assunto principal:** ' + a.analise.assunto_principal);
  linhas.push('- **Demanda/estoque:** ' + (a.analise.demanda_estoque ?? '—'));
  linhas.push('- **Incentivos/subsídios:** ' + (a.analise.incentivos_subsidios ?? '—'));
  linhas.push('- **CVR (taxa de conversão):** ' + (m.cvr_taxa_conversao ?? '—'));
  linhas.push('- **CTR (cliques):** ' + (m.ctr_cliques ?? '—'));
  linhas.push('- **Vendas/volume:** ' + (m.vendas_volume ?? '—'));
  if (a.analise.insight_estrategico) {
    linhas.push('- **Insight estratégico:** ' + a.analise.insight_estrategico);
  }
  linhas.push('');
}

linhas.push('---');
linhas.push('');
linhas.push('## Execução');
linhas.push('');
linhas.push('- Vídeos analisados: ' + analises.length);
linhas.push('- Sem transcrição disponível: ' + semTranscricao.length);
linhas.push('- Análises com JSON/schema inválido: ' + invalidos.length);
linhas.push('- Falhas de API: ' + falhas.length);
linhas.push('- Ignorados por baixo engajamento (< 1.000 views): ' + videosIgnorados.length);
for (const s of semTranscricao) linhas.push('  - Sem transcrição — ' + s);
for (const inv of invalidos) linhas.push('  - Inválido — ' + (inv.canal || '?') + ': "' + (inv.titulo || '?') + '" (' + (inv.erro || '') + ')');
for (const f of falhas) linhas.push('  - Falha — ' + f);
for (const vi of videosIgnorados) linhas.push('  - Ignorado — ' + vi);

const md = linhas.join('\n') + '\n';
const fileName = dataStr + '-youtube-etl.md';

// Resumo para o Telegram (limite da API: 4096 chars).
const resumoLinhas = ['YouTube ETL — ' + dataStr, ''];
if (analises.length === 0) {
  resumoLinhas.push('Nenhuma análise nova esta semana' + (meta.semVideos ? ' (sem vídeos novos)' : '') + '.');
} else {
  for (const a of analises) {
    resumoLinhas.push('• [' + a.canal + '] ' + a.titulo + ' (' + fmtNum(a.views) + ' views)');
    resumoLinhas.push('  https://youtu.be/' + a.videoId);
    resumoLinhas.push('  ' + a.analise.assunto_principal);
    if (a.analise.insight_estrategico) resumoLinhas.push('  Insight: ' + a.analise.insight_estrategico);
  }
}
resumoLinhas.push('');
resumoLinhas.push('Relatório completo: agents/youtube-etl/reports/' + fileName);
let resumo = resumoLinhas.join('\n');
if (resumo.length > 4000) resumo = resumo.slice(0, 4000) + '…';

return [{
  json: {
    filePath: '/data/youtube-etl/reports/' + fileName,
    fileName,
    telegramBody: JSON.stringify({ chat_id: $env.TELEGRAM_CHAT_ID, text: resumo }),
  },
  binary: {
    data: {
      data: Buffer.from(md, 'utf8').toString('base64'),
      mimeType: 'text/markdown',
      fileName,
    },
  },
}];

const videos = $input.all();
if (videos.length === 1 && videos[0].json.semVideos) {
  return videos; // sentinela de semana vazia — sem estatísticas a buscar
}
const ids = videos.map((v) => v.json.videoId).join(',');
return [{ json: { videoIdsCsv: ids } }];

const resp = $input.first().json;
const videos = $('Extrair VideoIds').all();

if (videos.length === 1 && videos[0].json.semVideos) {
  return videos;
}

const falhas = videos[0].json.falhas || [];

const stats = {};
for (const it of (resp.items || [])) {
  const s = it.statistics || {};
  stats[it.id] = {
    views: s.viewCount !== undefined ? Number(s.viewCount) : null,
    likes: s.likeCount !== undefined ? Number(s.likeCount) : null,
  };
}

// Vídeo com pouco alcance não compensa o custo de transcrição/análise —
// ignorado, não contado como falha (fica registrado à parte no rodapé).
const VIEWS_MINIMO = 1000;
const ignorados = [];
const mantidos = [];
for (const v of videos) {
  const s = stats[v.json.videoId];
  const views = s ? s.views : null;
  const likes = s ? s.likes : null;
  if (views !== null && views < VIEWS_MINIMO) {
    ignorados.push(v.json.canal + ': "' + v.json.titulo + '" (' + views + ' views)');
    continue;
  }
  mantidos.push({ json: { ...v.json, views, likes } });
}

if (mantidos.length === 0) {
  return [{ json: { todosAbaixoDoLimiar: true, falhas, videosIgnorados: ignorados } }];
}
mantidos[0].json.falhas = falhas;
mantidos[0].json.videosIgnorados = ignorados;
return mantidos;

const stdout = ($input.first().json && $input.first().json.stdout) || '';
const videos = $('Mesclar Estatisticas').all();

if (videos.length === 1 && (videos[0].json.semVideos || videos[0].json.todosAbaixoDoLimiar)) {
  return videos;
}

// Cada vídeo delimitado por ===VIDEO:<id>=== ... ===FIM=== no stdout combinado
// (o comando do yt-dlp roda os downloads em paralelo com xargs -P4).
const mapa = {};
for (const bloco of stdout.split('===VIDEO:')) {
  if (!bloco.trim()) continue;
  const fimId = bloco.indexOf('===');
  if (fimId === -1) continue;
  const id = bloco.slice(0, fimId);
  const resto = bloco.slice(fimId + 3);
  const fimMarcador = resto.indexOf('===FIM===');
  mapa[id] = fimMarcador === -1 ? resto : resto.slice(0, fimMarcador);
}

return videos.map((v) => ({
  json: { ...v.json, stdout: mapa[v.json.videoId] || '' },
}));
